Definition KS_afdA : list nat := Eval vm_compute in (BG.kept_list 60 PafdA.regs0 PafdA.regs_out0).
Lemma KS_afdA_ok : BG.kept_ok 60 PafdA.regs0 PafdA.regs_out0 KS_afdA = true.
Proof.
ltac2:(KReplay.run1 (kr_t_PnAEncDblP ()) [] "p;2p;4p;3p;1p-1p10000p4p710p9p1000\p4p70R0p1001Yp4p710p8P0p10025p4p710p8P0p1002Sp4p7210p8P0p10030p4p710p8P0p1003Np4p710p8g00EMj25Tg01b1j42Tg007Rj33Tg00XFj10Tf0R0#0#0#0#0p=4%00#0#0#0#0#0#0#0p=1g00UfR0g00VFR1'5g00^^#4#1#1#1#1#1#1#1g01c4g01d@g01ePC2=301do"). Qed.
Lemma afdA_conc fx R M (V : nat -> Z) :
  0 <= (V 2%nat) < 2 ^ 64 ->
  getr R (reg 2) = Z_to_bv 64 (V 2%nat) ->
  L5.img_clear M 1376256 1409024 -> L5.u64_at RSEGS M 1440376 2147450880 -> L5.u32_at RSEGS M 1440384 1 -> 140735332487232 <= (V 2%nat) <= 140737488355328 ->
  aligned (V 2%nat) 16 -> L5.writable RSEGS M ((V 2%nat) - 64) 64 ->
  exists fx' R' M', mem_grows M M'
    /\ (forall a : word, ~ (((V 2%nat) - 64) <= bv_unsigned a < ((V 2%nat) - 64) + 64) -> M' a = M a)
    /\ (forall i : Z, 0 <= i < 2 ^ 64 -> ~ (((V 2%nat) - 64) <= i < ((V 2%nat) - 64) + 64) -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i))
    /\ (msteps RSEGS (st fx R 0xc27a4 M) (st fx' R' 0xc27b8 M')
        /\ (forall x, In x KS_afdA -> getr R' (reg x) = getr R (reg x))
        /\ getr R' (reg 2) = Z_to_bv 64 ((V 2%nat) - 64)
        /\ L5.u64_at RSEGS M' ((V 2%nat) - 32) (bv_unsigned (getr R (reg 18)))
        /\ L5.u64_at RSEGS M' ((V 2%nat) - 24) (bv_unsigned (getr R (reg 9)))
        /\ L5.u64_at RSEGS M' ((V 2%nat) - 16) (bv_unsigned (getr R (reg 8)))
