Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Let LYa := PMA.ly_as0 L C LY.

(* [comment removed for export] *)
Definition str_push_back_short_specC : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (o sp r n : Z),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> PMSPA.entryA PMA.AD L ar R M sp r 1 -> PGSA.ffroomB PNRA.FCB 1 FF LK -> PMSPA.ffrsA FF sp ->
    getr R 10%bv = Z_to_bv 64 o -> PMSPA.aobjA FF o 24 -> o mod 8 = 0 ->
    vstr_at M o (PM.VShort n) -> n <= 21 ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)),
        regs_preserved R R' -> vstr_at M' o (PM.VShort (n + 1)) -> L5.u8_at RSEGS M' (o + 1 + n) (bv_unsigned (getr R 11%bv) mod 256) ->
        L5CA.ahpres L ar LB FF sp (PMSPA.pm_scr 1) [(o, 24)] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI LB FF LK' cr Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' r M' model') K) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R (PNL.pn_str_push_back PMA.AN) M model) K.

Theorem str_push_back_short_ok : str_push_back_short_specC.
Proof using All.
